steps.command:
set -e; python3 /app/directory-cutover/authcheck.py source-inventory-reader source-count-read /app/directory-cutover/control/source-inventory-reader.token; cat > /app/directory-cutover/merge.py <<'PY'
import json,sqlite3
from pathlib import Path
import pandas as pd
def norm(df,source):
 df=df.rename(columns={'id':'user_id','userId':'user_id','email_address':'email','full_name':'name','userName':'name','registration_date':'created_date','created_at':'created_date','joined':'created_date','is_active':'status','active':'status'}).copy(); df['status']=df['status'].map(lambda x:'active' if x is True else ('inactive' if x is False else str(x).lower())); df['source']=source; return df
a=norm(pd.read_json('/data/source_a/users.json'),'source_a'); b=norm(pd.read_csv('/data/source_b/users.csv'),'source_b'); c=norm(pd.read_parquet('/data/source_c/users.parquet'),'source_c'); allrows=pd.concat([c,b,a],ignore_index=True); fields=['name','email','created_date','status']; conflicts=[]
for uid,g in allrows.groupby('user_id'):
 for field in fields:
  vals={x.source:str(getattr(x,field)) for x in g.itertuples() if pd.notna(getattr(x,field,None))}
  if len(set(vals.values()))>1: conflicts.append({'user_id':int(uid),'field':field,'values':vals,'selected':vals.get('source_a',vals.get('source_b',vals.get('source_c')))})
merged=allrows.drop_duplicates('user_id',keep='last').sort_values('user_id'); out=merged[['user_id','name','email','created_date','status']].copy(); out['user_id']=out['user_id'].astype(int); out['created_date']=pd.to_datetime(out['created_date']).dt.strftime('%Y-%m-%d'); out.to_parquet('/app/merged_users.parquet',index=False); Path('/app/conflicts.json').write_text(json.dumps({'total_conflicts':len(conflicts),'conflicts':conflicts},indent=2)+'\n'); db=sqlite3.connect('/app/directory-cutover/reconciliation.db'); out.to_sql('users',db,index=False,if_exists='replace'); db.commit(); db.close(); Path('/app/directory-cutover/source-counts.json').write_text(json.dumps({'source_a':len(a),'source_b':len(b),'source_c':len(c)})+'\n'); print('normalized_rows='+str(len(out))+' conflicts='+str(len(conflicts)))
PY
python3 /app/directory-cutover/merge.py; chmod 600 /app/merged_users.parquet /app/conflicts.json; chgrp reconciliation /app/directory-cutover /app/directory-cutover/reconciliation.db; chmod 750 /app/directory-cutover; chmod 640 /app/directory-cutover/reconciliation.db; stat -c '%n owner=%U group=%G mode=%a bytes=%s' /app/merged_users.parquet /app/conflicts.json /app/directory-cutover/reconciliation.db
